  // ── batch 2 ──
  "Recommendation:": "Raccomandazione:", "Reference:": "Riferimento:", "Open findings:": "Rilievi aperti:", "Critical findings:": "Rilievi critici:", "Passed:": "Superati:", "Sessions:": "Sessioni:", "Runs:": "Esecuzioni:", "Intake risk score:": "Punteggio di rischio alla presa in carico:", "Applicable to:": "Applicabile a:",
